cd /tmp/symbols
# Let's use readelf with full symbols and search near those addresses
aarch64-linux-gnu-readelf -s libmonosgen-2.0.so.dbg 2>/dev/null | awk '{ 
  if (NF >= 8 && $2 ~ /^[0-9a-f]+$/) { 
    addr = strtonum("0x"$2); size = strtonum($3); name=$8
    if (addr <= 0x2f4b20 && (addr+size) > 0x2f4b20) print "0x2f4b20 in: " name " (base 0x"$2", size "$3", offset +" sprintf("0x%x", 0x2f4b20-addr) ")"
    if (addr <= 0x2f4c84 && (addr+size) > 0x2f4c84) print "0x2f4c84 in: " name " (base 0x"$2", size "$3", offset +" sprintf("0x%x", 0x2f4c84-addr) ")"
  }
}' | head -10

